#!/usr/bin/env node
// myNonRev build tool.
//   node tools/build.mjs           (re)generate build.json and precache.js (offline file list + build id used by the service worker)
//   node tools/build.mjs --check   fail if the generated files are out of date (use in CI)
// No dependencies. Deterministic: the same inputs always produce byte-identical outputs (no timestamps).
import { createHash } from 'node:crypto';
import { readFile, writeFile, readdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const CHECK = process.argv.includes('--check');

// Hash text files with LF line endings so a Windows checkout (CRLF) and the Linux runner agree on the id.
const TEXT_EXT = new Set(['.html', '.js', '.json', '.css', '.svg', '.webmanifest']);
const forHash = (rel, bytes) => (TEXT_EXT.has(path.extname(rel)) ? Buffer.from(bytes.toString('utf8').replace(/\r\n/g, '\n')) : bytes);

async function walk(dir) {
  const out = [];
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await walk(full)));
    else out.push(path.relative(ROOT, full).split(path.sep).join('/'));
  }
  return out;
}

const problems = [];

async function writeIfChanged(rel, text) {
  const file = path.join(ROOT, rel);
  let current = null;
  try { current = (await readFile(file, 'utf8')).replace(/\r\n/g, '\n'); } catch { /* missing */ }
  if (current === text) return;
  if (CHECK) { problems.push(`${rel} is out of date (run "npm run build")`); return; }
  await writeFile(file, text);
  console.log(`wrote ${rel}`);
}

// Everything the app needs offline. sw.js, build.json and precache.js are handled separately.
const runtime = [
  'index.html', 'manifest.webmanifest',
  ...(await walk(path.join(ROOT, 'css'))), ...(await walk(path.join(ROOT, 'js'))), ...(await walk(path.join(ROOT, 'icons'))),
].sort();

const hash = createHash('sha256');
for (const rel of [...runtime, 'sw.js']) {
  hash.update(`${rel}\0`);
  hash.update(forHash(rel, await readFile(path.join(ROOT, rel))));
  hash.update('\0');
}
const id = hash.digest('hex').slice(0, 12);
const files = ['./', ...runtime, 'build.json'];

await writeIfChanged('build.json', `${JSON.stringify({ id, files: files.length }, null, 2)}\n`);
await writeIfChanged('precache.js', `// Generated by tools/build.mjs - do not edit.\nself.MYNONREV_BUILD = ${JSON.stringify({ id, files }, null, 2)};\n`);

if (problems.length) {
  for (const p of problems) console.error(`ERROR ${p}`);
  process.exit(1);
}
console.log(`build ${id}: ${files.length} files${CHECK ? ' (up to date)' : ''}`);
